function thresholdProcess(data,w,h,opts){
  opts=opts||{};
  var thr=opts.threshold!=null?opts.threshold:128;
  var sm=opts.smooth!=null?opts.smooth:0;
  if(thr<0)thr=0; else if(thr>255)thr=255;
  if(sm<0)sm=0; else if(sm>1)sm=1;
  var bw=sm*40;
  var inv=opts.invert?1:0;
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<data.length;i+=4){
    var lum=0.299*data[i]+0.587*data[i+1]+0.114*data[i+2];
    var t;
    if(bw<0.5){ t = lum>=thr?1:0; }
    else if(lum<=thr-bw){ t=0; }
    else if(lum>=thr+bw){ t=1; }
    else { t=0.5+(lum-thr)/(2*bw); }
    if(inv) t=1-t;
    var v=t*255;
    out[i]=v;out[i+1]=v;out[i+2]=v;out[i+3]=data[i+3];
  }
  return out;
}

var EXPORTS={thresholdProcess:thresholdProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ThresholdForgePure = EXPORTS; }
